In Unreal Engine 5.6, implementing Enhanced Input in a `PlayerController` involves a few standard steps: defining the input assets as properties, registering the **Input Mapping Context (IMC)** via the **Local Player Subsystem**, and binding the **Input Actions (IA)** to specific callback functions.

Here is a complete, production-ready implementation.

### 1. Module Dependency
Ensure your `[ProjectName].Build.cs` file includes the **"EnhancedInput"** module.

```csharp
// YourProject.Build.cs
PublicDependencyModuleNames.AddRange(new string[] { "Core", "CoreUObject", "Engine", "InputCore", "EnhancedInput" });
```

---

### 2. Header File (.h)
We declare the `UInputMappingContext` and `UInputAction` pointers as `EditDefaultsOnly` so you can assign them in a Blueprint child of this controller.

```cpp
#pragma once

#include "CoreMinimal.h"
#include "GameFramework/PlayerController.h"
#include "InputActionValue.h" // Required for FInputActionValue
#include "MyPlayerController.generated.h"

/**
 * Custom PlayerController for Enhanced Input
 */
UCLASS()
class MYPROJECT_API AMyPlayerController : public APlayerController
{
	GENERATED_BODY()

protected:
	/** Called when the game starts */
	virtual void BeginPlay() override;

	/** Allows the PlayerController to set up custom input bindings */
	virtual void SetupInputComponent() override;

	// --- Enhanced Input Assets ---

	UPROPERTY(EditDefaultsOnly, BlueprintReadOnly, Category = "Input")
	class UInputMappingContext* DefaultMappingContext;

	UPROPERTY(EditDefaultsOnly, BlueprintReadOnly, Category = "Input")
	class UInputAction* MoveAction;

	UPROPERTY(EditDefaultsOnly, BlueprintReadOnly, Category = "Input")
	class UInputAction* LookAction;

	// --- Input Callbacks ---

	/** Handles WASD/Stick movement input (Vector2D) */
	void Move(const FInputActionValue& Value);

	/** Handles Mouse/Stick look input (Vector2D) */
	void Look(const FInputActionValue& Value);
};
```

---

### 3. Source File (.cpp)
In the source file, we access the `UEnhancedInputLocalPlayerSubsystem` to add the mapping context and use `UEnhancedInputComponent` to bind the functions.

```cpp
#include "MyPlayerController.h"
#include "EnhancedInputComponent.h"
#include "EnhancedInputSubsystems.h"
#include "GameFramework/Pawn.h"
#include "Engine/LocalPlayer.h"

void AMyPlayerController::BeginPlay()
{
	Super::BeginPlay();

	// Add the Input Mapping Context to the Local Player Subsystem
	if (UEnhancedInputLocalPlayerSubsystem* Subsystem = ULocalPlayer::GetSubsystem<UEnhancedInputLocalPlayerSubsystem>(GetLocalPlayer()))
	{
		if (DefaultMappingContext)
		{
			// Priority 0 is default; higher numbers override lower ones
			Subsystem->AddMappingContext(DefaultMappingContext, 0);
		}
	}
}

void AMyPlayerController::SetupInputComponent()
{
	Super::SetupInputComponent();

	// Cast the base InputComponent to the Enhanced Input Component
	if (UEnhancedInputComponent* EnhancedInputComponent = Cast<UEnhancedInputComponent>(InputComponent))
	{
		// Bind Move Action (Triggered = every frame while input is active)
		if (MoveAction)
		{
			EnhancedInputComponent->BindAction(MoveAction, ETriggerEvent::Triggered, this, &AMyPlayerController::Move);
		}

		// Bind Look Action (Triggered = every frame the mouse/stick moves)
		if (LookAction)
		{
			EnhancedInputComponent->BindAction(LookAction, ETriggerEvent::Triggered, this, &AMyPlayerController::Look);
		}
	}
}

void AMyPlayerController::Move(const FInputActionValue& Value)
{
	// Extract the Vector2D value from the action (X for Right/Left, Y for Forward/Backward)
	FVector2D MovementVector = Value.Get<FVector2D>();

	if (APawn* ControlledPawn = GetPawn())
	{
		// Find out which way is forward based on the controller rotation
		const FRotator Rotation = GetControlRotation();
		const FRotator YawRotation(0, Rotation.Yaw, 0);

		// Get forward vector
		const FVector ForwardDirection = FRotationMatrix(YawRotation).GetUnitAxis(EAxis::X);
		// Get right vector 
		const FVector RightDirection = FRotationMatrix(YawRotation).GetUnitAxis(EAxis::Y);

		// Add movement input to the pawn
		ControlledPawn->AddMovementInput(ForwardDirection, MovementVector.Y);
		ControlledPawn->AddMovementInput(RightDirection, MovementVector.X);
	}
}

void AMyPlayerController::Look(const FInputActionValue& Value)
{
	// Extract Vector2D for mouse/stick movement
	FVector2D LookAxisVector = Value.Get<FVector2D>();

	if (APawn* ControlledPawn = GetPawn())
	{
		// Add yaw and pitch input to the controller
		// X is Yaw (Left/Right), Y is Pitch (Up/Down)
		AddYawInput(LookAxisVector.X);
		AddPitchInput(LookAxisVector.Y);
	}
}
```

